import React from 'react';
import { useSelector } from 'react-redux';
import { Container, Typography, Box, TextField, Grid, Slider, FormControl, InputLabel, Select, MenuItem } from '@mui/material';
import ProductsList from '../components/ProductsList';
import { selectFilteredProducts, selectFeaturedProducts, setFilters, selectFilters } from '../features/productsSlice';
import { useDispatch } from 'react-redux';

const Products = () => {
  const dispatch = useDispatch();
  const products = useSelector(selectFilteredProducts);
  const featuredProducts = useSelector(selectFeaturedProducts);
  const filters = useSelector(selectFilters);

  return (
    <Container maxWidth="lg" sx={{ py: 4 }}>
      {/* Featured Products Section */}
      <Box sx={{ mb: 6 }}>
        <Typography variant="h4" component="h1" gutterBottom>
          Featured Products
        </Typography>
        <ProductsList products={featuredProducts} />
      </Box>

      {/* Filters Section */}
      <Box sx={{ mb: 4 }}>
        <Typography variant="h4" component="h2" gutterBottom>
          All Products
        </Typography>
        
        <Grid container spacing={3}>
          <Grid item xs={12} md={4}>
            <TextField
              fullWidth
              label="Search Products"
              value={filters.search}
              onChange={(e) => dispatch(setFilters({ search: e.target.value }))}
            />
          </Grid>
          
          <Grid item xs={12} md={3}>
            <Box sx={{ px: 2 }}>
              <Typography gutterBottom>Price Range</Typography>
              <Box sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
                <TextField
                  type="number"
                  size="small"
                  label="Min"
                  value={filters.priceRange[0]}
                  onChange={(e) => dispatch(setFilters({ 
                    priceRange: [Number(e.target.value), filters.priceRange[1]] 
                  }))}
                />
                <Typography>-</Typography>
                <TextField
                  type="number"
                  size="small"
                  label="Max"
                  value={filters.priceRange[1]}
                  onChange={(e) => dispatch(setFilters({ 
                    priceRange: [filters.priceRange[0], Number(e.target.value)] 
                  }))}
                />
              </Box>
            </Box>
          </Grid>

          <Grid item xs={12} md={4}>
            <FormControl fullWidth>
              <InputLabel>Category</InputLabel>
              <Select
                value={filters.category}
                onChange={(e) => dispatch(setFilters({ category: e.target.value }))}
              >
                <MenuItem value="all">All</MenuItem>
                <MenuItem value="electronics">Electronics</MenuItem>
                <MenuItem value="accessories">Accessories</MenuItem>
                <MenuItem value="clothing">Clothing</MenuItem>
              </Select>
            </FormControl>
          </Grid>
        </Grid>
      </Box>

      {/* Filtered Products */}
      <Box sx={{ mt: 4 }}>
        <ProductsList products={products} />
      </Box>
    </Container>
  );
};

export default Products;
